package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class IOUtils_skip_TriageGen0Test {

    /**
     * Note: The provided implementation of skip has a logical flaw in the return statement:
     * 'return available / numToSkip;'
     * If numToSkip becomes 0 (which it should after a successful skip), this will throw ArithmeticException (division by zero).
     * If numToSkip is not 0, it returns a ratio.
     * These tests are designed to cover the branches of the logic provided.
     */

    @Test(expected = ArithmeticException.class)
    public void testSkip_SuccessfulSkip_ThrowsArithmeticException() throws IOException {
        // This tests the case where numToSkip reaches 0 via input.skip()
        // causing 'return available / numToSkip' to be 'available / 0'
        byte[] data = new byte[10];
        InputStream input = new ByteArrayInputStream(data);
        IOUtils.skip(input, 5);
    }

    @Test(expected = ArithmeticException.class)
    public void testSkip_PartialSkipViaSkipMethod_ThrowsArithmeticException() throws IOException {
        // This tests the case where input.skip returns 0 immediately
        InputStream input = mock(InputStream.class);
        when(input.skip(anyLong())).thenReturn(0L);

        IOUtils.skip(input, 5);
    }

    @Test
    public void testSkip_SkipViaReadFully() throws IOException {
        // This tests the second while loop (the readFully block)
        // To avoid division by zero, we need numToSkip to remain > 0
        // However, the loop 'while (numToSkip > 0)' in the code will 
        // eventually make numToSkip 0 if readFully works correctly.

        // To trigger the branch where read < 1, we mock the stream to return -1
        InputStream input = mock(InputStream.class);
        when(input.skip(anyLong())).thenReturn(0L); // skip returns 0 to trigger break
        // Mock readFully behavior via the input stream
        // Since readFully is a static method in the same class, we can't easily mock it 
        // without PowerMock, so we use a real InputStream that returns EOF.

        InputStream eofInput = new InputStream() {
            @Override
            public int read() throws IOException {
                return -1;
            }
            @Override
            public long skip(long n) throws IOException {
                return 0;
            }
        };

        // In the provided code:
        // 1. input.skip(5) returns 0 -> break. numToSkip is still 5.
        // 2. enters 'if (numToSkip > 0)'
        // 3. readFully is called. read < 1 (returns -1 or 0) -> break.
        // 4. numToSkip is still 5.
        // 5. returns available (5) / numToSkip (5) = 1.

        long result = IOUtils.skip(eofInput, 5);
        assertEquals(1L, result);
    }

    @Test
    public void testSkip_ZeroNumToSkip() throws IOException {
        // If numToSkip is 0, the loops are skipped.
        // But the return is available / numToSkip -> 0 / 0 -> ArithmeticException
        try {
            IOUtils.skip(new ByteArrayInputStream(new byte[0]), 0);
        } catch (ArithmeticException e) {
            // Expected due to the provided code logic
        }
    }

    @Test
    public void testSkip_LargeSkipWithReadFully() throws IOException {
        // Testing the logic where numToSkip is reduced by readFully
        // We use a custom stream to control the 'read' amount
        InputStream input = new InputStream() {
            private int count = 0;
            @Override
            public int read() throws IOException {
                return (count++ < 2) ? 1 : -1;
            }
            @Override
            public long skip(long n) throws IOException {
                return 0; // Force use of readFully path
            }
        };

        // numToSkip = 3
        // loop 1: readFully returns 1. numToSkip = 2.
        // loop 2: readFully returns 1. numToSkip = 1.
        // loop 3: readFully returns -1. break.
        // return 3 / 1 = 3.

        // Note: This test assumes SKIP_BUF_SIZE is at least 1.
        // Since we cannot see SKIP_BUF_SIZE, we assume it's a standard buffer size.

        // We need to simulate readFully behavior. 
        // Since IOUtils.readFully is static, we rely on the real implementation.
        // The real readFully will call input.read() until len is met or -1.

        // Let's use a real ByteArrayInputStream for a controlled read
        byte[] data = new byte[]{1, 2, 3, 4, 5};
        InputStream realInput = new InputStream() {
            int pos = 0;
            @Override
            public int read() {
                return (pos < data.length) ? data[pos++] : -1;
            }
            @Override
            public long skip(long n) { return 0; }
        };

        // numToSkip = 2
        // 1. input.skip(2) returns 0.
        // 2. enters if (numToSkip > 0)
        // 3. readFully(input, buf, 0, 2) -> reads 2 bytes. numToSkip becomes 0.
        // 4. loop ends.
        // 5. returns 2 / 0 -> ArithmeticException.

        try {
            IOUtils.skip(realInput, 2);
        } catch (ArithmeticException e) {
            // Expected
        }
    }
}
